const BASE_CONTEXT: AlertContext = {
  alertType: AlertType.THRESHOLD,
  trackerName: "Tokyo trip",
  origin: "SFO",
  destination: "NRT",
  passengerSummary: "2 adults",
  cabin: "economy",
  currency: "USD",
  comparableCents: 124800,
  thresholdCents: 130000,
  thresholdBasis: ThresholdBasis.PARTY,
  priceScope: PriceScopeLabel.PARTY_TOTAL,
  outboundDate: "2026-10-12",
  returnDate: "2026-10-20",
  stops: 0,
  market: "us",
  observedAt: OBSERVED_AT,
  previousLowCents: null,
  dropAbsoluteCents: null,
  isBaseline: true,
  coverageChecked: null,
  coverageTotal: null,
  coverageComplete: false,
  link: "https://www.google.com/travel/flights?q=SFO+NRT",
  airlines: ["ANA", "United"],
};

describe("buildAlertText", () => {
  it("renders a baseline threshold alert exactly as Python does", () => {
    expect(buildAlertText(BASE_CONTEXT, TZ)).toBe(
      "<b>✈️ Threshold reached — SFO → NRT</b>\n" +
        "Tokyo trip\n" +
        "\n" +
        "$1,248 total for 2 adults · Economy\n" +
        "Oct 12–20 · Nonstop · ANA, United · US market\n" +
        "First observation for this configuration — recorded as the baseline, not a price drop.\n" +
        "Threshold: $1,300 (whole party)\n" +
        "Checked: Oct 2, 3:17 PM PDT\n" +
        "\n" +
        '<a href="https://www.google.com/travel/flights?q=SFO+NRT">' +
        "Open this search on Google Flights</a>\n" +
        "\n" +
        "<i>Price and availability can change before booking.</i>",
    );
  });

  it("renders a new low with the previous low, the drop and partial coverage", () => {
    const text = buildAlertText(
      {
        ...BASE_CONTEXT,
        alertType: AlertType.NEW_LOW,
        trackerName: "Kay & co <VIP>",
        comparableCents: 110650,
        previousLowCents: 124800,
        dropAbsoluteCents: 14150,
        isBaseline: false,
        stops: 1,
        coverageChecked: 18,
        coverageTotal: 24,
        coverageComplete: false,
        link: null,
        airlines: [],
      },
      TZ,
    );

    expect(text).toBe(
      "<b>✈️ New observed low — SFO → NRT</b>\n" +
        "Kay &amp; co &lt;VIP&gt;\n" +
        "\n" +
        "$1,106.50 total for 2 adults · Economy\n" +
        "Oct 12–20 · 1 stop · US market\n" +
        "Previous observed low: $1,248 · down $141.50\n" +
        "Threshold: $1,300 (whole party)\n" +
        "Checked: Oct 2, 3:17 PM PDT\n" +
        "Lowest observed among 18 of 24 date combinations checked.\n" +
        "\n" +
        "<i>Price and availability can change before booking.</i>",
    );
    // No link was supplied, so none is invented.
    expect(text).not.toContain("<a href");
  });

  it("labels an unconfirmed price basis and caps the airline list at three", () => {
    expect(
      buildAlertText(
        {
          ...BASE_CONTEXT,
          priceScope: PriceScopeLabel.UNKNOWN,
          thresholdBasis: ThresholdBasis.PER_TRAVELER,
          isBaseline: false,
          previousLowCents: 124800,
          dropAbsoluteCents: 0,
          returnDate: null,
          stops: null,
          cabin: "premium_economy",
          coverageChecked: 24,
          coverageTotal: 24,
          coverageComplete: true,
          link: null,
          airlines: ["ANA", "United", "JAL", "Delta"],
          market: "jp",
        },
        TZ,
      ),
    ).toBe(
      "<b>✈️ Threshold reached — SFO → NRT</b>\n" +
        "Tokyo trip\n" +
        "\n" +
        "$1,248 as reported by the provider (price basis unconfirmed) · Premium economy\n" +
        "Oct 12 · Stops unknown · ANA, United, JAL · JP market\n" +
        "Previous observed low: $1,248\n" +
        "Threshold: $1,300 (per traveler)\n" +
        "Checked: Oct 2, 3:17 PM PDT\n" +
        "Lowest across all 24 date combinations in this cycle.\n" +
        "\n" +
        "<i>Price and availability can change before booking.</i>",
    );
  });

  it("never calls a baseline a drop, even when a drop was computed", () => {
    const text = buildAlertText(
      { ...BASE_CONTEXT, isBaseline: true, previousLowCents: 130000, dropAbsoluteCents: 5200 },
      TZ,
    );
    expect(text).toContain("baseline");
    expect(text).not.toContain("down $");
  });

  it("escapes the link href as well as the visible text", () => {
    const text = buildAlertText(
      { ...BASE_CONTEXT, link: "https://example.test/?a=1&b=2<x>" },
      TZ,
    );
    expect(text).toContain('<a href="https://example.test/?a=1&amp;b=2&lt;x&gt;">');
  });

  it("titles an unrecognised cabin the way Python's str.title does", () => {
    expect(buildAlertText({ ...BASE_CONTEXT, cabin: "premium_flex" }, TZ)).toContain(
      "· Premium_Flex",
    );
  });

  it("renders the checked-at line in the configured timezone", () => {
    expect(buildAlertText(BASE_CONTEXT, "Asia/Tokyo")).toContain("Checked: Oct 3, 7:17 AM GMT+9");
  });

  it("is presentation only, so it can never serve as a dedupe surface", () => {
    // The same fare observed twice renders two different bodies, because the
    // checked-at line moves. Dedupe therefore has to key off the domain values
    // (see alertDedupeKey), never off this text.
    const later = { ...BASE_CONTEXT, observedAt: new Date("2026-10-02T23:17:00Z") };
    expect(buildAlertText(later, TZ)).not.toBe(buildAlertText(BASE_CONTEXT, TZ));

    // Conversely, a formatting-only difference in the input renders identically:
    // trailing-zero cents are one fare, not two.
    expect(buildAlertText({ ...BASE_CONTEXT, comparableCents: 124800 }, TZ)).toBe(
      buildAlertText(BASE_CONTEXT, TZ),
    );
  });
});

describe("buildTestMessage", () => {
  it("matches Python and mentions no fare data", () => {
    expect(buildTestMessage(TZ, OBSERVED_AT)).toBe(
      "<b>✈️ FlightNotify test message</b>\n" +
        "If you can read this, alerts are wired up correctly. This message contains no fare data.\n" +
        "Sent: Oct 2, 3:17 PM PDT",
    );
  });
});

describe("dateRange", () => {
  it("matches every Python branch", () => {
    expect(dateRange("2026-10-12", "2026-10-20")).toBe("Oct 12–20");
    expect(dateRange("2026-10-12", "2026-11-03")).toBe("Oct 12–Nov 3");
    // An incoherent pair must not render as the tidy "Oct 12-8".
    expect(dateRange("2026-10-12", "2026-10-08")).toBe("Oct 12, 2026 → Oct 8, 2026");
    expect(dateRange("2026-10-12", null)).toBe("Oct 12");
    expect(dateRange(null, "2026-11-03")).toBe("Nov 3");
    expect(dateRange(null, null)).toBe("Dates from provider");
  });

  it("spells out a same-day-number pair in different years", () => {
    expect(dateRange("2026-10-12", "2027-10-12")).toBe("Oct 12–Oct 12");
  });
});

describe("coverageSentence", () => {
  it("never calls a partial scan complete", () => {
    expect(coverageSentence(18, 24, false)).toBe(
      "Lowest observed among 18 of 24 date combinations checked.",
    );
    expect(coverageSentence(24, 24, true)).toBe(
      "Lowest across all 24 date combinations in this cycle.",
    );
    // Claimed complete but short of the total: still described as partial.
    expect(coverageSentence(20, 24, true)).toBe(
      "Lowest observed among 20 of 24 date combinations checked.",
    );
    expect(coverageSentence(null, 24, false)).toBe("Partial scan of 24 date combinations.");
  });

  it("says nothing when there was only ever one combination", () => {
    expect(coverageSentence(null, 1, true)).toBe("");
    expect(coverageSentence(1, null, true)).toBe("");
    expect(coverageSentence(1, 0, true)).toBe("");
  });
});
